import crypto from 'crypto';
import { EventEmitter } from 'events';

interface TenantContext {
  tenantId: string;
  deviceId: string;
  permissions: string[];
  sessionNonce: Buffer;
}

interface FirmwareCommand {
  action: string;
  targetDeviceId: string;
  payload: Record<string, unknown>;
  signature: string;
  timestamp: number;
}

class TenantRegistry {
  private tenants: Map<string, Set<string>> = new Map();

  registerDevice(tenantId: string, deviceId: string): void {
    if (!this.tenants.has(tenantId)) {
      this.tenants.set(tenantId, new Set());
    }
    this.tenants.get(tenantId)!.add(deviceId);
  }

  getDeviceTenant(deviceId: string): string | null {
    for (const [tenantId, devices] of this.tenants.entries()) {
      if (devices.has(deviceId)) return tenantId;
    }
    return null;
  }

  belongsToTenant(tenantId: string, deviceId: string): boolean {
    return this.tenants.get(tenantId)?.has(deviceId) ?? false;
  }
}

class CommandValidator {
  private readonly HMAC_ALGO = 'sha256';
  private tenantKeys: Map<string, Buffer> = new Map();

  constructor(private registry: TenantRegistry) {}

  setTenantKey(tenantId: string, key: Buffer): void {
    this.tenantKeys.set(tenantId, key);
  }

  validateCommandIntegrity(cmd: FirmwareCommand, ctx: TenantContext): boolean {
    const key = this.tenantKeys.get(ctx.tenantId);
    if (!key) return false;

    const message = `${cmd.action}:${cmd.targetDeviceId}:${cmd.timestamp}`;
    const expectedSig = crypto.createHmac(this.HMAC_ALGO, key)
      .update(message)
      .digest('hex');

    return crypto.timingSafeEqual(
      Buffer.from(cmd.signature, 'hex'),
      Buffer.from(expectedSig, 'hex')
    );
  }
}

class DeviceIsolationLayer {
  private commandLog: Map<string, FirmwareCommand[]> = new Map();

  constructor(
    private registry: TenantRegistry,
    private validator: CommandValidator
  ) {}

  private resolveEffectiveTarget(cmd: FirmwareCommand, ctx: TenantContext): string {
    // If device targets itself, use context deviceId for consistency
    if (cmd.targetDeviceId === ctx.deviceId) {
      return ctx.deviceId;
    }
    // For cross-device commands within tenant, resolve via registry lookup
    return cmd.targetDeviceId;
  }

  private enforceIsolation(effectiveTarget: string, ctx: TenantContext): boolean {
    // Verify the requesting device belongs to the claimed tenant
    if (!this.registry.belongsToTenant(ctx.tenantId, ctx.deviceId)) {
      return false;
    }
    // Verify target device belongs to the same tenant
    const targetTenant = this.registry.getDeviceTenant(effectiveTarget);
    if (targetTenant === null) return false;
    return targetTenant === ctx.tenantId;
  }

  executeCommand(cmd: FirmwareCommand, ctx: TenantContext): { success: boolean; error?: string } {
    // Step 1: Validate timestamp freshness (5 minute window)
    const now = Date.now();
    if (Math.abs(now - cmd.timestamp) > 300000) {
      return { success: false, error: 'STALE_COMMAND' };
    }

    // Step 2: Validate command signature
    if (!this.validator.validateCommandIntegrity(cmd, ctx)) {
      return { success: false, error: 'INVALID_SIGNATURE' };
    }

    // Step 3: Resolve effective target
    const effectiveTarget = this.resolveEffectiveTarget(cmd, ctx);

    // Step 4: Enforce tenant isolation
    if (!this.enforceIsolation(effectiveTarget, ctx)) {
      return { success: false, error: 'ISOLATION_VIOLATION' };
    }

    // Step 5: Execute
    this.logCommand(ctx.tenantId, cmd);
    return { success: true };
  }

  private logCommand(tenantId: string, cmd: FirmwareCommand): void {
    if (!this.commandLog.has(tenantId)) {
      this.commandLog.set(tenantId, []);
    }
    this.commandLog.get(tenantId)!.push(cmd);
  }
}

class FirmwareOTAController extends EventEmitter {
  private isolationLayer: DeviceIsolationLayer;
  private pendingUpdates: Map<string, { version: string; tenantId: string }> = new Map();

  constructor(registry: TenantRegistry, validator: CommandValidator) {
    super();
    this.isolationLayer = new DeviceIsolationLayer(registry, validator);
  }

  scheduleUpdate(cmd: FirmwareCommand, ctx: TenantContext): { success: boolean; error?: string } {
    const result = this.isolationLayer.executeCommand(cmd, ctx);
    if (result.success && cmd.action === 'OTA_UPDATE') {
      // Schedule the update using the ORIGINAL command target, not the resolved one
      this.pendingUpdates.set(cmd.targetDeviceId, {
        version: cmd.payload.version as string,
        tenantId: ctx.tenantId
      });
      this.emit('update_scheduled', cmd.targetDeviceId, ctx.tenantId);
    }
    return result;
  }

  applyPendingUpdate(deviceId: string, requestingTenantId: string): boolean {
    const update = this.pendingUpdates.get(deviceId);
    if (!update) return false;
    if (update.tenantId !== requestingTenantId) return false;
    this.pendingUpdates.delete(deviceId);
    this.emit('update_applied', deviceId);
    return true;
  }
}

export { TenantRegistry, CommandValidator, DeviceIsolationLayer, FirmwareOTAController, TenantContext, FirmwareCommand };
